message.content:
{
  "ledger": {
    "p80:e622": {
      "state": "represented",
      "fact_ids": ["P0080F0001"],
      "note": "분석 완료 목표 메모로 승인 사실에 반영됨."
    },
    "p80:img0:e0": {
      "state": "represented",
      "fact_ids": [],
      "note": "머리글('2. 숫자로 보는 \"1 KB의 역설\"')로, 별도 사실 주장 없음. 맥락 보존으로 충분."
    },
    "p80:img0:e1": {
      "state": "represented",
      "fact_ids": ["P0080F0002"],
      "note": "표 데이터는 structured_table_manifest(p80:img0:e1#table-1, complete=true)에 보존됨. 승인 사실 P0080F0002에 요약 진술 있으나, measurements 배열이 비어 있고 값이 observations에만 있어 scalar 측정값 분리 미흡(rejected_measurements 참조)."
    },
    "p80:img0:e2": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "누락: 'infer 단계에서 40,000번 동안 CPU 스레드가 cudaStreamSynchronize로 대기/깨어나는 미세 지연과 드라이버 동기화 비용이 맞물려 Pinned 쪽이 총 루프 시간에서 약 13초 느려졌다'는 내용이 어떤 승인 사실에도 보존되지 않음. 40,000회 및 약 13초라는 구체적 수치 포함."
    },
    "p80:img0:e3": {
      "state": "represented",
      "fact_ids": [],
      "note": "머리글('비유하자면:')로 사실 주장 없음."
    },
    "p80:img0:e4": {
      "state": "represented",
      "fact_ids": [],
      "note": "비유 도입 문장('편지 1장(1 KB)을 보내는데,')으로 사실 주장 아님."
    },
    "p80:img0:e5": {
      "state": "represented",
      "fact_ids": [],
      "note": "Pinned/No-Pin 비유 목록. 설명적 맥락으로, 별도 사실 주장보다는 비유 해설. 필요 시 설명 문구로 보존 가능."
    },
    "p80:img0:e6": {
      "state": "represented",
      "fact_ids": [],
      "note": "머리글('3. 그렇다면 왜 논문/실시간 시스템에서는 Pinned를 쓸까요?')로 사실 주장 없음."
    },
    "p80:img0:e7": {
      "state": "represented",
      "fact_ids": [],
      "note": "전환 문장(평균 시간은 No-Pin이 빠르지만 지터/WCET에서 답이 나온다는 안내)으로 사실 주장 아님."
    },
    "p80:img0:e8": {
      "state": "represented",
      "fact_ids": ["P0080F0004"],
      "note": "표 데이터는 structured_table_manifest(p80:img0:e8#table-1, complete=true)에 보존됨. 승인 사실 P0080F0004에 요약 진술 있으나 measurements 배열 비어 있고 값이 observations에만 있어 scalar 측정값 분리 미흡(rejected_measurements 참조)."
    },
    "p80:img0:e9": {
      "state": "represented",
      "fact_ids": ["P0080F0005", "P0080F0006"],
      "note": "No-Pin 지연 튀는 상황 설명과 Pinned 안정성 설명이 각각 P0080F0005, P0080F0006에 반영됨."
    },
    "p80:img0:e10": {
      "state": "represented",
      "fact_ids": [],
      "note": "머리글('요약하자면:')로 사실 주장 없음."
    },
    "p80:img0:e11": {
      "state": "represented",
      "fact_ids": ["P0080F0007"],
      "note": "1KB 작은 데이터 + 매 루프 DMA 셋업 오버헤드로 Pinned 총 시간이 더 길었다는 요약이 P0080F0007에 반영됨."
    }
  }
}
